const { SMTPServer } = require('smtp-server');
const { simpleParser } = require('mailparser');
const bcrypt = require('bcryptjs');
const Mailbox = require('../models/Mailbox');
const EmailMessage = require('../models/EmailMessage');
const emailService = require('../services/email.service');
const logger = require('../config/logger');

// Authenticate user against Mailbox database for Port 587
const onAuth = async (auth, session, callback) => {
  try {
    const mailbox = await Mailbox.findOne({ email: auth.username });
    if (!mailbox) {
      return callback(new Error('Invalid username or password'));
    }

    const isMatch = await bcrypt.compare(auth.password, mailbox.password_hash);
    if (!isMatch) {
      return callback(new Error('Invalid username or password'));
    }

    // Attach mailbox to session for later use
    session.user = {
      _id: mailbox._id,
      email: mailbox.email,
      domain_id: mailbox.domain_id,
      name: `${mailbox.first_name || ''} ${mailbox.last_name || ''}`.trim()
    };

    callback(null, { user: mailbox.email });
  } catch (err) {
    logger.error('Auth Error:', err);
    callback(new Error('Authentication failed'));
  }
};

// Validate Recipient
// If Authenticated: Allow any recipient (Outbound)
// If Localhost: Allow (System Notifications)
// If Guest: Recipient must be a local Mailbox (Inbound)
const onRcptTo = async (address, session, callback) => {
  try {
    // 1. Allow Authenticated Users (Outbound)
    if (session.user) {
      return callback(); 
    }

    // 2. Allow Localhost / Internal System (Password Resets, Alerts)
    // This prevents "550 Relaying Denied" when the app sends to itself
    const remoteIP = session.remoteAddress;
    if (remoteIP === '127.0.0.1' || remoteIP === '::1' || remoteIP === '::ffff:127.0.0.1') {
        return callback();
    }

    // 3. Inbound (Guest/Internet) -> Check if recipient exists locally
    const mailbox = await Mailbox.findOne({ email: address.address });
    if (!mailbox) {
      // Reject unknown recipients to prevent backscatter/spam
      return callback(new Error('550 Relaying denied'));
    }

    // Valid local recipient
    callback();
  } catch (err) {
    logger.error('RcptTo Error:', err);
    callback(new Error('Internal server error'));
  }
};

// Process Data Stream
const onData = (stream, session, callback) => {
  simpleParser(stream, async (err, parsed) => {
    if (err) {
      logger.error('Parse Error:', err);
      return callback(new Error('Error parsing email'));
    }

    try {
      const { from, to, subject, text, html } = parsed;
      const fromAddress = from ? from.text : ''; 

      // Handle To addresses (can be array or object)
      const toAddressStr = Array.isArray(to) 
        ? to.map(t => t.text).join(', ') 
        : (to ? to.text : '');

      if (session.user) {
        // --- OUTBOUND (Authenticated User) ---

        // 1. Save to Sender's 'Sent' folder
        await EmailMessage.create({
          mailbox_id: session.user._id,
          direction: 'outbound',
          from: fromAddress,
          to: toAddressStr,
          subject: subject || '',
          text_body: text || '',
          html_body: html || '',
          folder: 'sent',
          is_read: true
        });
        logger.info(`OUTBOUND saved to DB for ${session.user.email}`);

        // 2. DELIVER THE EMAIL (Relay)
        const recipients = session.envelope.rcptTo.map(r => r.address);
        for (const recipient of recipients) {
             await emailService.sendEmail(fromAddress, recipient, subject, text, html);
        }

      } else {
        // --- INBOUND (Internet or Localhost) ---
        // Save to EACH valid local Recipient's 'Inbox'
        const recipients = session.envelope.rcptTo;

        let deliveredCount = 0;
        for (const recipient of recipients) {
          const mailbox = await Mailbox.findOne({ email: recipient.address });
          if (mailbox) {
            await EmailMessage.create({
              mailbox_id: mailbox._id,
              direction: 'inbound',
              from: fromAddress,
              to: recipient.address,
              subject: subject || '',
              text_body: text || '',
              html_body: html || '',
              folder: 'inbox',
              is_read: false
            });
            logger.info(`INBOUND saved for ${mailbox.email}`);
            deliveredCount++;
          } else {
             // If we allowed it in rcptTo (e.g. localhost) but user doesn't exist, we just drop it gracefully here.
             logger.warn(`Dropped email for unknown user ${recipient.address} (allowed via whitelist)`);
          }
        }
      }

      callback();
    } catch (error) {
      logger.error('Data Save Error:', error);
      callback(new Error('Error saving to database'));
    }
  });
};

// Server for Port 25 (Inbound, No Auth required for delivery to local users)
const server25 = new SMTPServer({
  secure: false,
  authOptional: true,
  disabledCommands: ['STARTTLS'],
  onRcptTo,
  onData,
  logger: false 
});

// Server for Port 587 (Submission, Auth Required)
const server587 = new SMTPServer({
  secure: false,
  authOptional: false, // Auth is mandatory
  disabledCommands: ['STARTTLS'],
  onAuth,
  onRcptTo,
  onData,
  logger: false
});

module.exports = {
  start: (port25 = 25, port587 = 587) => {
    server25.listen(port25, () => logger.info(`SMTP Inbound Server (Public) running on port ${port25}`));
    server587.listen(port587, () => logger.info(`SMTP Submission Server (Client) running on port ${port587}`));
  }
};

const dns = require('dns').promises;
const nodemailer = require('nodemailer');
const Mailbox = require('../models/Mailbox');
const Domain = require('../models/Domain');
const Client = require('../models/Client'); // Added to fetch Company Name
const EmailMessage = require('../models/EmailMessage');
const SystemConfig = require('../models/SystemConfig');
const logger = require('../config/logger');

/**
 * Helper: Extract pure email from "Name <email>" format
 */
const extractEmail = (fullAddress) => {
    if (!fullAddress) return '';
    const match = fullAddress.match(/<([^>]+)>/);
    return match ? match[1] : fullAddress;
};

/**
 * Helper: Send email to external server
 */
const deliverExternal = async (senderEmail, recipientEmail, subject, text, html) => {
  try {
    const cleanRecipient = extractEmail(recipientEmail);
    const cleanSender = extractEmail(senderEmail);

    const recipientDomain = cleanRecipient.split('@')[1];
    if (!recipientDomain) throw new Error('Invalid recipient domain');

    // 1. Resolve MX Records
    const mxRecords = await dns.resolveMx(recipientDomain);
    if (!mxRecords || mxRecords.length === 0) throw new Error('No MX records found for domain');

    // Sort by priority (lowest number first)
    const bestMx = mxRecords.sort((a, b) => a.priority - b.priority)[0].exchange;

    logger.info(`Resolving delivery for ${cleanRecipient}: via ${bestMx}`);

    // 2. Prepare DKIM Signing (Look up using CLEAN sender email)
    let dkimOptions = undefined;

    // Check if sender is a Mailbox first
    const senderMailbox = await Mailbox.findOne({ email: cleanSender.toLowerCase() }).populate('domain_id');

    if (senderMailbox && senderMailbox.domain_id && senderMailbox.domain_id.dkim_private_key) {
      dkimOptions = {
        domainName: senderMailbox.domain_id.name,
        keySelector: 'default',
        privateKey: senderMailbox.domain_id.dkim_private_key
      };
    } else {
         // Fallback: Check if the domain itself exists and has keys (for System Emails)
         const senderDomainPart = cleanSender.split('@')[1];
         if (senderDomainPart) {
             const senderDomain = await Domain.findOne({ name: senderDomainPart.toLowerCase() });
             if (senderDomain && senderDomain.dkim_private_key) {
                 dkimOptions = {
                    domainName: senderDomain.name,
                    keySelector: 'default',
                    privateKey: senderDomain.dkim_private_key
                };
             }
         }
    }

    // 3. Get System Config for HELO
    let heloName = process.env.MY_HOSTNAME || 'smtp-server.local';
    try {
        const config = await SystemConfig.findOne({ singleton: true });
        if (config && config.smtp_hostname) {
            heloName = config.smtp_hostname;
        }
    } catch(e) { /* Fallback */ }

    // 4. Create Transporter
    const transporter = nodemailer.createTransport({
      host: bestMx,
      port: 25,
      secure: false,
      tls: { rejectUnauthorized: false },
      name: heloName,
      dkim: dkimOptions
    });

    // 5. Send (Use original senderEmail which might include "Name <email>")
    await transporter.sendMail({
      from: senderEmail, 
      to: recipientEmail,
      subject: subject,
      text: text,
      html: html
    });

    logger.info(`External Delivery Success: ${cleanRecipient} (HELO: ${heloName})`);
    return true;
  } catch (error) {
    logger.error(`External Delivery Failed to ${recipientEmail}: ${error.message}`);
    return false;
  }
};

/**
 * Delivers an email (System or User) handling both local and external recipients.
 */
const sendEmail = async (from, to, subject, text, html) => {
    try {
        const cleanTo = extractEmail(to).toLowerCase().trim();

        // Check if local (Case Insensitive)
        const recipientMailbox = await Mailbox.findOne({ email: cleanTo });

        if (recipientMailbox) {
            // --- LOCAL DELIVERY ---
            await EmailMessage.create({
                mailbox_id: recipientMailbox._id,
                direction: 'inbound',
                from: extractEmail(from), // Store clean email in DB for consistency
                to: cleanTo,
                subject: subject || '',
                text_body: text || '',
                html_body: html || '',
                folder: 'inbox',
                is_read: false
            });
            logger.info(`Internal Delivery: ${from} -> ${cleanTo}`);
            return true;
        } else {
            // --- EXTERNAL DELIVERY ---
            return await deliverExternal(from, to, subject, text, html);
        }
    } catch (err) {
        logger.error('Email Service Error:', err);
        return false;
    }
};

/**
 * Sends a system notification (e.g. OTP)
 * Constructs a Friendly From Address: "Company Name" <noreply@domain.com>
 */
const sendSystemEmail = async (to, subject, text, html) => {
    let fromEmail = 'noreply@system.local';
    let fromName = 'Eeina Security'; // Default Name

    try {
        // 1. Fetch Company Name from Admin Client
        const admin = await Client.findOne().sort({ created_at: 1 });
        if (admin && admin.company_name) {
            fromName = admin.company_name;
        }

        // 2. Priority: Use a Verified Domain (noreply@verified.com)
        const validDomain = await Domain.findOne({ is_verified: true });

        if (validDomain) {
            fromEmail = `noreply@${validDomain.name}`;
            logger.info(`System Email: Auto-selected sender ${fromEmail} from verified domains.`);
        } else {
            // 3. Fallback: Check System Configuration
            const config = await SystemConfig.findOne({ singleton: true });
            if (config && config.system_email_address && !config.system_email_address.includes('system.local')) {
                fromEmail = config.system_email_address;
            }
        }
    } catch (e) {
        logger.error('System Email Sender Error:', e);
    }

    // Construct "Name <email>" format
    const from = `"${fromName}" <${fromEmail}>`;

    return await sendEmail(from, to, subject, text, html);
};

module.exports = {
    deliverExternal,
    sendEmail,
    sendSystemEmail
};

