                    <div>
                         <input 
                          type="text" 
                          placeholder="First Name (Optional)"
                          name="first_name"
                          className="w-full border-gray-200 bg-gray-50 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                        />
