                    </div>
                    <div className="sm:col-span-2 lg:col-span-4 flex justify-end">
                        <button type="submit" className="bg-blue-600 text-white px-6 py-2 rounded-lg text-sm font-medium hover:bg-blue-700 transition shadow-sm">
                           Create Mailbox
                        </button>
                    </div>
                  </form>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
