import React, { createContext, useContext, useState, useCallback } from 'react';

type ToastType = 'success' | 'error' | 'info';

interface Toast {
  id: number;
  message: string;
  type: ToastType;
}

interface ToastContextType {
  addToast: (message: string, type?: ToastType) => void;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export const ToastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const addToast = useCallback((message: string, type: ToastType = 'success') => {
    const id = Date.now();
    setToasts((prev) => [...prev, { id, message, type }]);

    // Auto remove after 4 seconds
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 4000);
  }, []);

  const removeToast = (id: number) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  };

  return (
    <ToastContext.Provider value={{ addToast }}>
      {children}
      <div className="fixed bottom-4 right-4 z-[9999] flex flex-col gap-2 pointer-events-none">
        {toasts.map((toast) => (
          <div
            key={toast.id}
            className={`pointer-events-auto flex items-center w-full max-w-sm overflow-hidden bg-white rounded-lg shadow-lg border-l-4 animate-in slide-in-from-right-full duration-300 ${
              toast.type === 'success' ? 'border-green-500' : 
              toast.type === 'error' ? 'border-red-500' : 'border-blue-500'
            }`}
          >
            <div className="p-4 flex items-center">
              <div className="flex-shrink-0">
                {toast.type === 'success' && (
                  <svg className="w-5 h-5 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
                )}
                {toast.type === 'error' && (
                  <svg className="w-5 h-5 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                )}
                {toast.type === 'info' && (
                  <svg className="w-5 h-5 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                )}
              </div>
              <div className="ml-3">
                <p className="text-sm font-medium text-gray-900">{toast.message}</p>
              </div>
              <div className="ml-4 flex-shrink-0 flex">
                <button
                  onClick={() => removeToast(toast.id)}
                  className="inline-flex text-gray-400 hover:text-gray-500 focus:outline-none"
                >
                  <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
};

export const useToast = () => {
  const context = useContext(ToastContext);
  if (context === undefined) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return context;
};

import React, { useState, useEffect } from 'react';
import api from './api';
import LandingView from './views/LandingView';
import AuthView from './views/AuthView';
import ClientDashboard from './views/ClientDashboard';
import WebmailView from './views/WebmailView';
import Spinner from './components/Spinner';
import { User } from './types';
import { ToastProvider } from './components/ToastContext';

export default function App() {
  const [view, setView] = useState<'landing' | 'login' | 'client-dashboard' | 'webmail-dashboard'>('landing');
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Check auth on load
  useEffect(() => {
    const initAuth = async () => {
      const token = localStorage.getItem('smtp_token');
      const role = localStorage.getItem('smtp_role');

      if (token && role) {
        try {
          if (role === 'client') {
             const res = await api.get('/api/account/profile');
             setUser({ ...res.data, role: 'client', token });
             setView('client-dashboard');
          } else if (role === 'mailbox') {
             const res = await api.get('/api/webmail/profile');
             setUser({ ...res.data, role: 'mailbox', token });
             setView('webmail-dashboard');
          }
        } catch (err) {
          // Token invalid or session expired
          console.error("Session fetch failed", err);
          localStorage.removeItem('smtp_token');
          localStorage.removeItem('smtp_role');
          setView('landing');
        }
      } else {
         setView('landing');
      }
      setLoading(false);
    };

    initAuth();
  }, []);

  const handleLoginSuccess = (userData: User) => {
    setUser(userData);
    localStorage.setItem('smtp_role', userData.role);
    setView(userData.role === 'client' ? 'client-dashboard' : 'webmail-dashboard');
  };

  const handleLogout = () => {
    localStorage.removeItem('smtp_token');
    localStorage.removeItem('smtp_role');
    setUser(null);
    setView('landing');
  };

  const handleUserUpdate = (updates: Partial<User>) => {
    if (user) {
        setUser({ ...user, ...updates });
    }
  };

  if (loading) {
    return (
        <div className="min-h-screen bg-gray-50 flex items-center justify-center">
            <div className="flex flex-col items-center">
                <Spinner />
                <p className="mt-4 text-gray-500 text-sm">Loading...</p>
            </div>
        </div>
    );
  }

  return (
    <ToastProvider>
      {view === 'landing' && <LandingView onNavigate={(v) => setView(v as any)} />}

      {view === 'login' && (
        <AuthView onSuccess={handleLoginSuccess} onBack={() => setView('landing')} />
      )}

      {view === 'client-dashboard' && user && (
        <ClientDashboard user={user} onLogout={handleLogout} onUserUpdate={handleUserUpdate} />
      )}

      {view === 'webmail-dashboard' && user && (
        <WebmailView user={user} onLogout={handleLogout} />
      )}
    </ToastProvider>
  );
}

