        }
      }
    }, [html]);
    return <iframe ref={iframeRef} title="email-body" className="w-full h-full border-0 bg-white" sandbox="allow-same-origin allow-popups" />;
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">

