const { SMTPServer } = require('smtp-server');
const { simpleParser } = require('mailparser');
const bcrypt = require('bcryptjs');
const Mailbox = require('../models/Mailbox');
const EmailMessage = require('../models/EmailMessage');
const emailService = require('../services/email.service');
const logger = require('../config/logger');

// Authenticate user against Mailbox database for Port 587
const onAuth = async (auth, session, callback) => {
  try {
    const mailbox = await Mailbox.findOne({ email: auth.username.toLowerCase() });
    if (!mailbox) {
      return callback(new Error('Invalid username or password'));
    }

    const isMatch = await bcrypt.compare(auth.password, mailbox.password_hash);
    if (!isMatch) {
      return callback(new Error('Invalid username or password'));
    }

    // Attach mailbox to session for later use
    session.user = {
      _id: mailbox._id,
      email: mailbox.email,
      domain_id: mailbox.domain_id,
      name: `${mailbox.first_name || ''} ${mailbox.last_name || ''}`.trim()
    };

    callback(null, { user: mailbox.email });
  } catch (err) {
    logger.error('Auth Error:', err);
    callback(new Error('Authentication failed'));
  }
};

// Validate Recipient
// If Authenticated: Allow any recipient (Outbound)
// If Localhost: Allow (System Notifications)
// If Guest: Recipient must be a local Mailbox (Inbound)
const onRcptTo = async (address, session, callback) => {
  try {
    // 1. Allow Authenticated Users (Outbound)
    if (session.user) {
      return callback(); 
    }

    // 2. Allow Localhost / Internal System (Password Resets, Alerts)
    // This prevents "550 Relaying Denied" when the app sends to itself
    const remoteIP = session.remoteAddress;
    if (remoteIP === '127.0.0.1' || remoteIP === '::1' || remoteIP === '::ffff:127.0.0.1') {
        return callback();
    }

    // 3. Inbound (Guest/Internet) -> Check if recipient exists locally
    const mailbox = await Mailbox.findOne({ email: address.address.toLowerCase() });
    if (!mailbox) {
      // Reject unknown recipients to prevent backscatter/spam
      return callback(new Error('550 Relaying denied'));
    }

    // Valid local recipient
    callback();
  } catch (err) {
    logger.error('RcptTo Error:', err);
    callback(new Error('Internal server error'));
  }
};

// Process Data Stream
const onData = (stream, session, callback) => {
  simpleParser(stream, async (err, parsed) => {
    if (err) {
      logger.error('Parse Error:', err);
      return callback(new Error('Error parsing email'));
    }

    try {
      const { from, to, subject, text, html, attachments } = parsed;
      const fromAddress = from ? from.text : 'Unknown'; 

      // Handle To addresses (can be array or object)
      const toAddressStr = Array.isArray(to) 
        ? to.map(t => t.text).join(', ') 
        : (to ? to.text : '');

      // Prepare attachments for storage
      const processedAttachments = attachments ? attachments.map(att => ({
        filename: att.filename || 'unnamed',
        contentType: att.contentType,
        content: att.content,
        size: att.size
      })) : [];

      if (session.user) {
        // --- OUTBOUND (Authenticated User) ---

        // 1. Save to Sender's 'Sent' folder
        if (session.user._id) {
            await EmailMessage.create({
              mailbox_id: session.user._id,
              direction: 'outbound',
              from: fromAddress,
              to: toAddressStr,
              subject: subject || '',
              text_body: text || '',
              html_body: html || '',
              has_attachments: processedAttachments.length > 0,
              attachments: processedAttachments,
              folder: 'sent',
              is_read: true
            });
            logger.info(`OUTBOUND saved to DB for ${session.user.email}`);
        }

        // 2. DELIVER THE EMAIL (Relay)
        const recipients = session.envelope.rcptTo.map(r => r.address);
        for (const recipient of recipients) {
             await emailService.sendEmail(fromAddress, recipient, subject, text, html, {
                attachments: processedAttachments
             });
        }

      } else {
        // --- INBOUND (Internet or Localhost) ---
        // Save to EACH valid local Recipient's 'Inbox'
        const recipients = session.envelope.rcptTo;

        let deliveredCount = 0;
        for (const recipient of recipients) {
          // Look up mailbox using lowercased address
          const mailbox = await Mailbox.findOne({ email: recipient.address.toLowerCase() });

          // CRITICAL FIX: Ensure mailbox AND mailbox._id exist before creating
          if (mailbox && mailbox._id) {
            await EmailMessage.create({
              mailbox_id: mailbox._id,
              direction: 'inbound',
              from: fromAddress,
              to: recipient.address,
              subject: subject || '',
              text_body: text || '',
              html_body: html || '',
              has_attachments: processedAttachments.length > 0,
              attachments: processedAttachments,
              folder: 'inbox',
              is_read: false
            });
            logger.info(`INBOUND saved for ${mailbox.email}`);
            deliveredCount++;
          } else {
             // If we allowed it in rcptTo (e.g. localhost) but user doesn't exist, we just drop it gracefully here.
             logger.warn(`Dropped email for unknown user ${recipient.address} (allowed via whitelist)`);
          }
        }
      }

      callback();
    } catch (error) {
      logger.error('Data Save Error:', error);
      callback(new Error('Error saving to database'));
    }
  });
};

// Server for Port 25 (Inbound, No Auth required for delivery to local users)
const server25 = new SMTPServer({
  secure: false,
  authOptional: true,
  disabledCommands: ['STARTTLS'],
  onRcptTo,
  onData,
  logger: false 
});

// Server for Port 587 (Submission, Auth Required)
const server587 = new SMTPServer({
  secure: false,
  authOptional: false, // Auth is mandatory
  disabledCommands: ['STARTTLS'],
  onAuth,
  onRcptTo,
  onData,
  logger: false
});

module.exports = {
  start: (port25 = 25, port587 = 587) => {
    server25.listen(port25, () => logger.info(`SMTP Inbound Server (Public) running on port ${port25}`));
    server587.listen(port587, () => logger.info(`SMTP Submission Server (Client) running on port ${port587}`));
  }
};

const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const Mailbox = require('../models/Mailbox');
const EmailMessage = require('../models/EmailMessage');
const { authenticateWebmail } = require('../middleware/auth');
const logger = require('../config/logger');
const emailService = require('../services/email.service');

// Webmail Login
router.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const mailbox = await Mailbox.findOne({ email });
    if (!mailbox) return res.status(400).json({ error: 'Invalid credentials' });

    const isMatch = await bcrypt.compare(password, mailbox.password_hash);
    if (!isMatch) return res.status(400).json({ error: 'Invalid credentials' });

    const token = jwt.sign({ mailbox_id: mailbox._id, email: mailbox.email }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });

    res.json({ 
        token, 
        email: mailbox.email,
        first_name: mailbox.first_name,
        last_name: mailbox.last_name
    });
  } catch (err) {
    logger.error('Webmail Login Error:', err);
    res.status(500).json({ error: 'Login failed' });
  }
});

// Change Password
router.put('/password', authenticateWebmail, async (req, res) => {
  try {
    const { currentPassword, newPassword } = req.body;

    if (!newPassword || newPassword.length < 6) {
        return res.status(400).json({ error: 'New password must be at least 6 characters' });
    }

    const mailbox = await Mailbox.findById(req.user.mailbox_id);
    if (!mailbox) return res.status(404).json({ error: 'Mailbox not found' });

    const isMatch = await bcrypt.compare(currentPassword, mailbox.password_hash);
    if (!isMatch) return res.status(400).json({ error: 'Incorrect current password' });

    const salt = await bcrypt.genSalt(10);
    mailbox.password_hash = await bcrypt.hash(newPassword, salt);
    await mailbox.save();

    res.json({ message: 'Password updated successfully' });
  } catch (err) {
    logger.error('Webmail Password Update Error:', err);
    res.status(500).json({ error: 'Failed to update password' });
  }
});

// Get Webmail Profile
router.get('/profile', authenticateWebmail, async (req, res) => {
    try {
        const mailbox = await Mailbox.findById(req.user.mailbox_id);
        if(!mailbox) return res.status(404).json({error: "Mailbox not found"});
        res.json({
            email: mailbox.email,
            first_name: mailbox.first_name,
            last_name: mailbox.last_name,
            recovery_email: mailbox.recovery_email
        });
    } catch(err) {
        res.status(500).json({error: "Server Error"});
    }
});

// Webmail Messages (Paginated)
router.get('/messages', authenticateWebmail, async (req, res) => {
  try {
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 20;
    const folder = req.query.folder || 'inbox';
    const skip = (page - 1) * limit;

    const query = { 
        mailbox_id: req.user.mailbox_id,
        folder: folder
    };

    // Exclude 'attachments.content' to keep response size light
    const [messages, total] = await Promise.all([
        EmailMessage.find(query)
          .select('-attachments.content') 
          .sort({ created_at: -1 })
          .skip(skip)
          .limit(limit),
        EmailMessage.countDocuments(query)
    ]);

    res.json({
        messages,
        pagination: {
            total,
            page,
            pages: Math.ceil(total / limit)
        }
    });
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

// Download Attachment
router.get('/messages/:id/download/:filename', authenticateWebmail, async (req, res) => {
  try {
    const message = await EmailMessage.findOne({
      _id: req.params.id,
      mailbox_id: req.user.mailbox_id
    });

    if (!message) return res.status(404).json({ error: 'Message not found' });

    const attachment = message.attachments.find(att => att.filename === req.params.filename);
    if (!attachment) return res.status(404).json({ error: 'Attachment not found' });

    res.setHeader('Content-Type', attachment.contentType || 'application/octet-stream');
    res.setHeader('Content-Disposition', `attachment; filename="${attachment.filename}"`);
    res.send(attachment.content);
  } catch (err) {
    logger.error('Download Error:', err);
    res.status(500).json({ error: 'Failed to download attachment' });
  }
});

// Mark Message as Read
router.patch('/messages/:id/read', authenticateWebmail, async (req, res) => {
    try {
        const msg = await EmailMessage.findOneAndUpdate(
            { _id: req.params.id, mailbox_id: req.user.mailbox_id },
            { is_read: true },
            { new: true }
        ).select('-attachments.content');
        if (!msg) return res.status(404).json({ error: 'Message not found' });
        res.json(msg);
    } catch (err) {
        res.status(500).json({ error: 'Failed to update message' });
    }
});

// Batch Delete Messages
router.post('/messages/batch-delete', authenticateWebmail, async (req, res) => {
    try {
        const { ids } = req.body;
        if (!ids || !Array.isArray(ids)) return res.status(400).json({ error: 'Invalid IDs provided' });

        await EmailMessage.deleteMany({
            _id: { $in: ids },
            mailbox_id: req.user.mailbox_id
        });

        res.json({ message: 'Messages deleted' });
    } catch (err) {
        logger.error('Batch Delete Error:', err);
        res.status(500).json({ error: 'Failed to delete messages' });
    }
});

// Delete Single Message
router.delete('/messages/:id', authenticateWebmail, async (req, res) => {
  try {
    const msg = await EmailMessage.findOneAndDelete({
      _id: req.params.id,
      mailbox_id: req.user.mailbox_id
    });

    if (!msg) return res.status(404).json({ error: 'Message not found' });

    res.json({ message: 'Message deleted successfully' });
  } catch (err) {
    logger.error('Delete Message Error:', err);
    res.status(500).json({ error: 'Failed to delete message' });
  }
